export default function Home() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (containerRef.current) {
      const video = containerRef.current.querySelector('video');
      if (video) {
        video.muted = true;
        video.play().catch((err) => console.log('Autoplay log:', err));
      }
    }
  }, []);

  return (
    <main className="w-full min-h-screen bg-[#FAF9F6] text-slate-900">
      <div className="relative w-full">
        <div
          ref={containerRef}
          className="w-full relative singlefile-root"
          dangerouslySetInnerHTML={{ __html: heroHtml }}
        />
        <HoverGradientNavBar />
      </div>
      <div className="relative z-20 bg-[#FAF9F6]">
        <LandingAccordionItem />
      </div>
      <div className="relative z-20">
        <ContributorsWall />
      </div>
      <div className="relative z-20">
        <ServicesFanHover />
      </div>
      <div className="relative z-20">
        <ZoomParallax />
      </div>
      <div className="relative z-20">
        <IndustryGrid />
      </div>
      <div className="relative z-20">
        <TestimonialsSection />
      </div>
      <div className="relative z-20 h-[30vh] min-h-[250px] w-full overflow-hidden bg-[#FAF9F6]">
        <PerspectiveMarquee />
      </div>
      <div className="relative z-20">
        <ScrollReelSection />
      </div>
      <FAQ1 />
      <CinematicFooter />
    </main>
  );
}
